// #f7124a (67983c2cf6fb3e0dfbf7124a) — лист «צריכים עזרה?» как в Figma 827:2940 / 845:3380. Проверено 04.11.2026
// (390, 1440, Pixel 6), «עבר QA» 04.11:
//  - три чипа типа обращения высотой 46 в один ряд (было 44);
//  - «אפשר גם לפנות ישירות»: телефон и e-mail — две отдельные ссылки (tel:/mailto:), у каждой padding 12, между ними ≥8;
//  - поле описания высотой 110 без ручки изменения размера (resize: none);
//  - лист открывается и из сбоя тех. проверки — тот же компонент, «תקלה טכנית» выбрана.
// НЕ prod-safe: каждый тест создаёт кандидата «QA-AUTO-f7124a-…» (business, link_only), не удаляется → @data.
// Обращение не отправляется («שליחה» не нажимается), звонок не начинается (blockCallStarts).
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { blockCallStarts } from './support';
import { newCandidateLink, tapBtn } from './a11y-support';
import {
  HELP, TECH, closeHelp, failGetUserMedia, gapBetween, helpSheet, openHelp, openWelcome, sheetMetrics, toTechCheckIntro,
} from './help-1104-support';

const HASH = '#f7124a · #67983c2cf6fb3e0dfbf7124a';

/** Замеры листа по «מה רצוי» / ответу программиста 02.11 (коммит 0015d1e). */
async function expectSheetLayout(page: Page, label: string) {
  await expect(page.getByText(HELP.direct).first(), `${label}: блок прямого обращения`).toBeVisible();
  const m = await sheetMetrics(helpSheet(page));

  // Чипы: 3 шт., высота 46, один ряд.
  expect(m.chips.map((c) => c.name), `${label}: чипы`).toEqual(HELP.chips);
  for (const c of m.chips) expect(c.h, `${label}: высота чипа «${c.name}»`).toBeCloseTo(46, 0);
  const tops = m.chips.map((c) => c.top);
  expect(Math.max(...tops) - Math.min(...tops), `${label}: чипы не в один ряд (top ${tops.join('/')})`).toBeLessThanOrEqual(1);

  // Телефон и e-mail — две отдельные ссылки с отступом 12 и промежутком ≥8.
  expect(m.tel, `${label}: нет ссылки tel:`).not.toBeNull();
  expect(m.mail, `${label}: нет ссылки mailto:`).not.toBeNull();
  expect(m.nested, `${label}: ссылки вложены одна в другую`).toBe(false);
  expect(m.tel!.text, `${label}: в ссылке телефона e-mail`).not.toContain('@');
  expect(m.mail!.text, `${label}: в ссылке e-mail цифры телефона`).not.toMatch(/\d{7,}/);
  for (const [k, l] of [['tel', m.tel!], ['mail', m.mail!]] as const) {
    expect(l.pt, `${label}: padding-top ${k}`).toBeCloseTo(12, 0);
    expect(l.pb, `${label}: padding-bottom ${k}`).toBeCloseTo(12, 0);
  }
  expect(gapBetween(m.tel!, m.mail!), `${label}: промежуток между телефоном и e-mail`).toBeGreaterThanOrEqual(7.5);

  // Поле описания: 110, без resize.
  expect(m.textarea, `${label}: нет поля описания`).not.toBeNull();
  expect(m.textarea!.h, `${label}: высота поля описания`).toBeCloseTo(110, 0);
  expect(m.textarea!.resize, `${label}: resize поля описания`).toBe('none');
}

test.describe(`Кандидат — лист «צריכים עזרה?»: чипы, контакты, поле (${HASH})`, () => {
  test(`с экрана открытия: 3 чипа высотой 46 в один ряд; телефон и e-mail — отдельные ссылки (padding 12, промежуток ≥8); поле 110 без resize @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-f7124a-M-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (только экран открытия), не удаляется` });
    const blocked = await blockCallStarts(page);

    await openWelcome(page, link);
    await openHelp(page);
    // Источник: реджект (чипы 44, слипшиеся контакты) + Figma 827:2940 / 845:3380.
    await expectSheetLayout(page, `своё окно ${page.viewportSize()!.width}`);
    await closeHelp(page);
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`390 и 1440: те же замеры листа с экрана открытия @desktop @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-f7124a-D-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (только экран открытия), не удаляется` });
    const blocked = await blockCallStarts(page);

    await openWelcome(page, link);
    for (const w of [390, 1440]) {
      await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
      await openHelp(page);
      await expectSheetLayout(page, `@${w}`);
      await closeHelp(page);
    }
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`из сбоя тех. проверки (нет микрофона) → «${HELP.techLink}»: тот же лист, «תקלה טכנית» выбрана, замеры те же @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-f7124a-T-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие, тех. проверка не пройдена), не удаляется` });
    await page.addInitScript(failGetUserMedia, 'NotFoundError');
    const blocked = await blockCallStarts(page);

    await toTechCheckIntro(page, link);
    await tapBtn(page, TECH.start);
    await expect(page.getByText(TECH.failed).first()).toBeVisible({ timeout: 30_000 });
    await openHelp(page, () => page.getByRole('button', { name: HELP.techLink, exact: true }).first().click());

    // Источник: «Что перепроверить» п.3 брифа — открытие из сбоя тех. проверки, тот же компонент.
    await expect(page.getByRole('radio', { name: 'תקלה טכנית' })).toBeChecked();
    await expectSheetLayout(page, 'из сбоя тех. проверки');
    await closeHelp(page);
    await expect(page.getByText(TECH.failed).first()).toBeVisible();
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });
});
